    private static final int W=595,H=842,M=30,R=W-M,MAXY=788;
    private static final int INK=Color.rgb(28,39,60), MUTED=Color.rgb(105,116,133),
            ACCENT=Color.rgb(60,78,173), LINE=Color.rgb(224,228,236), PALE=Color.rgb(241,243,250);
    private final PdfDocument doc=new PdfDocument();
