    private static String clean(String s){if(s==null)return "";return s.replaceAll("[\\p{Cntrl}]"," ").replaceAll("\\s+"," ").trim();}
    private static String get(JSONObject obj,String name){return clean(obj==null?"":obj.optString(name,""));}
    private void write(String s,float x,float baseline,float pt,int color,boolean bold){
        paint.setColor(color);paint.setStyle(Paint.Style.FILL);paint.setTypeface(Typeface.create(Typeface.DEFAULT,bold?Typeface.BOLD:Typeface.NORMAL));paint.setTextSize(pt);
