    private void rect(float l,float t,float r,float b,int color){paint.setColor(color);paint.setStyle(Paint.Style.FILL);canvas.drawRect(l,t,r,b,paint);}
    private String clip(String str,float width,float point){
        str=clean(str);paint.setTypeface(Typeface.DEFAULT);paint.setTextSize(point);
        if(paint.measureText(str)<=width)return str;
        while(str.length()>1&&paint.measureText(str+"…")>width)str=str.substring(0,str.length()-1);
        return str+"…";
    }
    private ArrayList<String> lines(String str,float width,float pt,int maximum){
        ArrayList<String> out=new ArrayList<>();StringBuilder buf=new StringBuilder();
        for(String word:clean(str).split(" ")){if(word.isEmpty())continue;
            String candidate=buf.length()==0?word:buf+" "+word;
            paint.setTextSize(pt);
            if(paint.measureText(candidate)>width&&buf.length()>0){out.add(clip(buf.toString(),width,pt));buf=new StringBuilder(word);}
            else buf=new StringBuilder(candidate);
        }
        if(buf.length()>0)out.add(clip(buf.toString(),width,pt));
        if(out.size()>maximum){ArrayList<String> capped=new ArrayList<>(out.subList(0,maximum));capped.set(maximum-1,clip(capped.get(maximum-1)+"…",width,pt));return capped;}
        return out;
    }
