    private static String first(JSONObject p,String a,String b){String s=get(p,a);return s.isEmpty()?get(p,b):s;}
    private static String normalizeSemester(String semester){
        String val=clean(semester).toUpperCase(Locale.ROOT).replace("SEMESTER","SEM").replaceAll("\\s+", " ").trim();
        Matcher m=Pattern.compile("(?:SEM\\s*[-:]?\\s*)?(\\d{1,2}|X|IX|VIII|VII|VI|V|IV|III|II|I)$").matcher(val);
        if(m.find()){String n=m.group(1);String[] roman={"I","II","III","IV","V","VI","VII","VIII","IX","X"};
            for(int i=0;i<roman.length;i++)if(n.equals(roman[i]))return "Semester "+(i+1);
            try{return "Semester "+Integer.parseInt(n);}catch(Exception ignored){}
        }
        return val.isEmpty()?"Semester unspecified":clean(semester);
    }
    private static String subjectCode(JSONObject s){
        String code=get(s,"code").toUpperCase(Locale.ROOT).replaceAll("\\s+","");
        if(code.isEmpty()){
            Matcher m=Pattern.compile("\\(([A-Za-z]{2,8}[-/]?\\d{2,5}[A-Za-z]?)\\)$").matcher(get(s,"name"));
            if(m.find())code=m.group(1).toUpperCase(Locale.ROOT);
        }
        return code;
    }
    private static String assessment(JSONObject result,JSONObject subject){
        String kind=(get(subject,"examType")+" "+get(result,"exam")).toUpperCase(Locale.ROOT)
                .replaceAll("[._-]+"," ").replaceAll("\\s+"," ").trim();
        if(kind.matches(".*\\b(SESSIONAL|SESSIONAL|ST|MIDTERM|MID TERM|INTERNAL TEST|CLASS TEST|CT)\\s*1\\b.*"))return "st1";
        if(kind.matches(".*\\b(SESSIONAL|SESSIONAL|ST|MIDTERM|MID TERM|INTERNAL TEST|CLASS TEST|CT)\\s*2\\b.*"))return "st2";
        if(kind.matches(".*\\bPUT\\b.*")||kind.contains("PRE UNIVERSITY")||kind.contains("PREUNIVERSITY"))return "put";
        return "other";
    }
    private static String collegeMarks(JSONObject s){String marks=get(s,"marks"),maximum=get(s,"maxMarks");
        return marks+(maximum.isEmpty()?"":"/"+maximum);
    }
    private static String aktuMarks(JSONObject s){
        String internal=get(s,"internal"),external=get(s,"external"),grade=get(s,"grade"),back=get(s,"backPaper");
        ArrayList<String> a=new ArrayList<>();
        if(!internal.isEmpty())a.add("I:"+internal);
        if(!external.isEmpty())a.add("E:"+external);
        if(!back.isEmpty()&&!back.equals("--")&&!back.equals("-"))a.add("B:"+back);
        if(!grade.isEmpty())a.add("G:"+grade);
        if(a.isEmpty())return get(s,"marks");
        return String.join(" ",a);
    }
    private static void append(Subject x,String field,String val){
        val=clean(val);if(val.isEmpty())return;
        if(field.equals("aktu"))x.aktu=addOnce(x.aktu,val);
        else if(field.equals("st1"))x.st1=addOnce(x.st1,val);
        else if(field.equals("st2"))x.st2=addOnce(x.st2,val);
        else if(field.equals("put"))x.put=addOnce(x.put,val);
        else x.other=addOnce(x.other,val);
    }
    private static String addOnce(String old,String value){
        if(old.isEmpty())return value;if(old.equals(value)||(" · "+old+" · ").contains(" · "+value+" · "))return old;
        return old+" · "+value;
    }
    static final class Subject {String name="",code="",aktu="",st1="",st2="",put="",other="";}
    static final class Semester {
        String name,sgpa="",cgpa="",status="",marks="",session="";
        final LinkedHashMap<String,Subject> subjects=new LinkedHashMap<>();
        Semester(String value){name=value;}
    }
    private static LinkedHashMap<String,Semester> combine(JSONArray results){
        LinkedHashMap<String,Semester> semesters=new LinkedHashMap<>();
        for(int i=0;i<results.length();i++){
            JSONObject result=results.optJSONObject(i);if(result==null)continue;
            String semester=normalizeSemester(get(result,"semester"));
            Semester group=semesters.get(semester);if(group==null){group=new Semester(semester);semesters.put(semester,group);}
            boolean university=get(result,"source").equals("aktu");
            if(university){if(!get(result,"sgpa").isEmpty())group.sgpa=get(result,"sgpa");
                if(!get(result,"cgpa").isEmpty())group.cgpa=get(result,"cgpa");
                if(!get(result,"status").isEmpty())group.status=get(result,"status");
                if(!get(result,"marksTotal").isEmpty())group.marks=get(result,"marksTotal");
            }
            if(group.session.isEmpty())group.session=get(result,"session");
            JSONArray subjects=result.optJSONArray("subjects");if(subjects==null)continue;
            for(int j=0;j<subjects.length();j++){
                JSONObject s=subjects.optJSONObject(j);if(s==null)continue;
                String code=subjectCode(s),name=get(s,"name");if(name.isEmpty()&&code.isEmpty())continue;
                // Only identical normalized codes are merged; same-name fallbacks stay in the semester.
                String key=code.isEmpty()?"NAME:"+name.toUpperCase(Locale.ROOT):"CODE:"+code;
                Subject row=group.subjects.get(key);if(row==null){row=new Subject();row.name=name;row.code=code;group.subjects.put(key,row);}
                if(row.name.isEmpty()&&!name.isEmpty())row.name=name;
                if(university)append(row,"aktu",aktuMarks(s));
                else append(row,assessment(result,s),collegeMarks(s));
            }
        }
        return semesters;
    }
