        if(y+h>MAXY){newPage();head();}
        int top=y;
        for(int k=0;k<title.size();k++)write(title.get(k),M+5,top+12+k*10,8.1f,INK,k==0);
        if(!r.code.isEmpty())write(clip(r.code,181,7.3f),M+5,top+12+10*title.size(),7.3f,MUTED,false);
        for(int k=0;k<akt.size();k++)write(akt.get(k),M+200,top+12+k*10,7.7f,INK,k==0);
        write(clip(r.st1.isEmpty()?"—":r.st1,57,8.0f),M+317,top+13,8,INK,true);
        write(clip(r.st2.isEmpty()?"—":r.st2,57,8.0f),M+380,top+13,8,INK,true);
        write(clip(r.put.isEmpty()?"—":r.put,40,8.0f),M+442,top+13,8,INK,true);
        write(clip(r.other.isEmpty()?"—":r.other,48,7.5f),M+485,top+13,7.5f,INK,false);
        y+=h;rect(M,y,R,y+0.7f,LINE);y+=3;
    }
    static byte[] render(String payload)throws Exception{return render(payload,null);}
    static byte[] render(String payload,Bitmap photo)throws Exception{
        JSONObject obj=new JSONObject(payload);JSONObject person=obj.optJSONObject("candidate");JSONArray results=obj.optJSONArray("results");
        if(person==null||results==null)throw new IllegalArgumentException("Candidate and result data required");
        if(results.length()>160)throw new IllegalArgumentException("Too many result entries");
        CandidateReport report=new CandidateReport();try{
            report.newPage();report.identity(person,photo);
            LinkedHashMap<String,Semester> semesters=combine(results);
            report.ensure(25);report.write("CONSOLIDATED SUBJECT RESULTS",M,report.y+12,11.3f,INK,true);report.y+=29;
            if(semesters.isEmpty()){report.write("No saved exam results",M+4,report.y+12,9,MUTED,false);report.y+=20;}
            for(Map.Entry<String,Semester> e:semesters.entrySet()){
                Semester sem=e.getValue();report.semesterHeader(sem);
                report.head();
                if(sem.subjects.isEmpty()){report.ensure(20);report.write("No subject marks captured",M+6,report.y+12,8,MUTED,false);report.y+=23;}
                else for(Subject row:sem.subjects.values())report.row(row);
                report.y+=13;
            }
            report.finish();ByteArrayOutputStream out=new ByteArrayOutputStream();report.doc.writeTo(out);return out.toByteArray();
        }finally{report.doc.close();}
    }
}

